from research_journey import STORY

ROOT = Path(__file__).parent
NAV = [('index.html','Home'), ('research-journey.html','Research journey'), ('projects.html','Current projects'), ('students.html','Students'), ('teaching.html','Teaching')]

def write_page(filename, title, eyebrow, intro, body):
    nav = ''.join(f'<a href="{url}"'+(' aria-current="page"' if url == filename else '')+f'>{label}</a>' for url,label in NAV)
    heading = f'<section class="page-heading"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="intro">{intro}</p></section>'
    if filename == 'index.html':
        heading = '''<section class="editorial-hero"><div class="hero-copy"><p class="eyebrow">Aneta Lisowska · Assistant Professor in AI and Health</p><h1>AI for survival<br><em>and quality of life</em></h1><p class="hero-intro">My long-term research goal is to maximise survival and quality of life, with AI supporting decisions across the patient journey.</p><p class="hero-detail">The scientific question is how to estimate patient state from uncertain evidence, predict how that state may change given different actions, and support sequences of decisions towards these measurable outcomes.</p><div class="hero-actions"><a class="button" href="projects.html">Explore the research programme <span aria-hidden="true">↗</span></a><a class="text-link" href="mailto:a.j.lisowska@vu.nl">Get in touch ↗</a></div></div><figure class="hero-portrait"><img src="assets/portrait.webp" alt="Aneta Lisowska" width="480" height="560"><figcaption>Vrije Universiteit Amsterdam<br>Cancer Center Amsterdam UMC</figcaption></figure></section>'''
    content = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title} | Aneta Lisowska</title><meta name="description" content="{escape(intro, quote=True)}">
<meta name="theme-color" content="#562435"><link rel="stylesheet" href="style.css"></head>
<body><a class="skip" href="#main">Skip to content</a>
<header><div class="header-inner"><a class="brand" href="index.html">Aneta Lisowska<span>AI &amp; Health</span></a>
<nav aria-label="Main navigation">{nav}</nav></div></header>
<main id="main">{heading}{body}</main>
<footer><div><strong>Aneta Lisowska</strong><p>AI &amp; Health · Amsterdam</p><a class="contact-email" href="mailto:a.j.lisowska@vu.nl">a.j.lisowska@vu.nl</a></div><div class="footer-links"><a href="https://www.linkedin.com/in/anetajl/">LinkedIn ↗</a><a href="https://scholar.google.com/citations?user=-hXV9EsAAAAJ&amp;hl=en">Google Scholar ↗</a></div></footer>
</body></html>'''
    (ROOT / filename).write_text(content, encoding='utf-8')

def card(label, title, text, extra=''):
    return f'<article class="card"><p class="eyebrow">{label}</p><h2>{title}</h2><p>{text}</p>{extra}</article>'

def paper_link(url, label):
    return f'<a class="paper-link" href="{escape(url, quote=True)}">{label} <span aria-hidden="true">↗</span></a>'

def research_themes():
    return '''<section class="section method-section" aria-labelledby="methods"><div class="section-title"><p class="eyebrow">Three connected research pillars</p><h2 id="methods">Understanding, reliance, and action</h2><p class="intro">The pillars serve one programme objective: better survival and quality of life. They connect uncertainty in patient-state estimates, the consequences of actions, and how people use AI in care decisions.</p></div><div class="method-grid">
<article class="method explain"><svg viewBox="0 0 300 165" role="img" aria-label="A conceptual diagram linking input features to a model prediction"><path d="M30 42H115M30 82H90M30 122H135" stroke="#762F43" stroke-width="15"/><path d="M155 42L205 82M155 82H205M155 122L205 82" stroke="#C9A7A1" fill="none" stroke-width="2"/><circle cx="235" cy="82" r="26" fill="#762F43"/><path d="m225 82 7 7 14-17" stroke="white" stroke-width="3" fill="none"/></svg><p class="eyebrow">01 · Explainability</p><h3>What drives a prediction?</h3><p>Investigating whether explanations help clinicians recognise misleading advice. Clinical meaning, agreement with reader attention, and faithfulness to model behaviour are separate questions.</p><a href="students.html#student-papers">Explore explainability research ↗</a></article>
<article class="method sequential"><svg viewBox="0 0 300 165" role="img" aria-label="A conceptual feedback loop from observation to action to outcome"><path d="M60 63Q150-15 240 63M240 105Q150 180 60 105" fill="none" stroke="#C9A7A1" stroke-width="2"/><path d="m228 60 13 4-2-13M72 108l-13-4 2 13" fill="none" stroke="#562435" stroke-width="3"/><circle cx="60" cy="82" r="25" fill="#562435"/><circle cx="150" cy="42" r="21" fill="#E6D7D1"/><circle cx="240" cy="82" r="25" fill="#562435"/><text x="60" y="87" text-anchor="middle" fill="white" font-size="12">Observe</text><text x="150" y="46" text-anchor="middle" fill="#562435" font-size="12">Act</text><text x="240" y="87" text-anchor="middle" fill="white" font-size="12">Learn</text></svg><p class="eyebrow">02 · Sequential decision-making</p><h3>Which action, and when?</h3><p>Studying policies that optimise expected long-term outcomes. In the oncology vision, the objectives are survival and quality of life; engagement, adherence, response, and toxicity are intermediate measures whose relationship to those outcomes needs testing.</p><a href="projects.html">Explore personalized interventions ↗</a></article>
<article class="method uncertainty"><svg viewBox="0 0 300 165" role="img" aria-label="Conceptual narrow and broad distributions represent different levels of model uncertainty"><path d="M25 135H275" stroke="#C9A7A1"/><path d="M35 134C90 134 95 15 135 15S172 134 225 134" stroke="#762F43" stroke-width="3" fill="#E6D7D1" fill-opacity=".5"/><path d="M25 134C65 134 70 62 155 62S238 134 275 134" stroke="#562435" stroke-width="3" fill="none" stroke-dasharray="5 5"/></svg><p class="eyebrow">03 · Uncertainty</p><h3>How much should we rely on AI?</h3><p>Estimating patient state from incomplete and variable observations. Uncertainty affects both our assessment at one visit and the changes we infer between visits.</p><a href="students.html#student-papers">Explore uncertainty research ↗</a></article>
</div><div class="decision-question"><span aria-hidden="true">↓</span><h3>How does AI influence human decisions?</h3><p>A decision is an intermediate step. The overarching evaluation asks what AI contributes to survival and quality of life over the patient journey.</p></div><p class="figure-note">Conceptual illustrations of the research themes.</p></section>'''

write_page('index.html', 'AI for survival and quality of life', 'Aneta Lisowska · Assistant Professor in AI and Health',
    'A research programme on explainable sequential decisions across the patient journey, with survival and quality of life as the long-term objectives.', '''
<section class="research-context" aria-label="Research context"><p><span>Research setting</span>AI research &amp; clinical practice</p><p><span>Long-term objectives</span>Survival &amp; quality of life</p><p><span>Scope</span>Decisions across the patient journey</p></section>
<section class="research-statement"><p class="eyebrow">The scientific vision</p><div><h2>What sequence of decisions<br><em>leads to better patient outcomes?</em></h2><p>The goal is measurable: survival and patient-reported quality of life over time. My programme asks how AI introduced at different points in care could contribute to those outcomes, from diagnosis and treatment selection to monitoring, patient support, and recovery.</p><p>Reinforcement learning provides a framework for studying policies that optimise expected long-term outcomes. This requires estimating the patient’s current state, modelling possible state transitions given actions, and learning how the consequences of one decision affect the next.</p><p>Uncertainty and explainability are integral to this problem: what do the observations tell us, how reliable are predicted consequences, and how can clinicians and patients use that evidence appropriately?</p><a class="text-link" href="research-journey.html">How this programme developed ↗</a></div></section>'''+research_themes()+'''
<section class="section decision-framework" aria-labelledby="framework-title"><div class="section-title"><p class="eyebrow">The sequential-decision framework</p><h2 id="framework-title">Patient state. Possible transitions.<br><em>Actions with long-term consequences.</em></h2><p class="intro">AI can contribute at each stage of care by updating what we know about a patient and evaluating what could happen next under different actions.</p></div><ol class="framework-stages"><li><span>01 · Observe</span><h3>Gather evidence</h3><p>Images, signals, patient reports, and treatment history provide observations across the care journey.</p></li><li><span>02 · Estimate</span><h3>Infer patient state</h3><p>Represent the current state as an uncertainty-aware estimate, rather than assume it is fully observed.</p></li><li><span>03 · Predict</span><h3>Model transitions</h3><p>Estimate how patient state may change given a candidate action, including treatment or supportive intervention.</p></li><li><span>04 · Decide</span><h3>Evaluate actions</h3><p>Study policies that account for consequences over time and support clinically appropriate choices.</p></li></ol><div class="outcome-objective"><p class="eyebrow">Long-term optimisation objective</p><h3>Maximise survival <em>and quality of life</em></h3><p>Evaluate survival and patient-reported quality of life. Test how intermediate measures, including response, toxicity, adherence, and engagement, relate to these outcomes.</p></div><p class="framework-feedback">Actions are followed by new observations and feedback, informing the next state estimate and decision.</p><p class="figure-note">This is the research vision. Current projects investigate parts of the framework; an end-to-end oncology policy and its effect on patient outcomes remain to be developed and validated.</p></section>
<section class="section selected-work" aria-labelledby="selected-work"><div class="section-title"><p class="eyebrow">Flagship publications</p><h2 id="selected-work">Contributions to the research programme</h2></div>
<article class="evidence-row"><p class="eyebrow">Explainability · 2026</p><div><h3><a href="https://doi.org/10.3389/frai.2026.1819422">Which explanations are clinically impactful?</a></h3><p>A systematic review examining clinical impact and evaluation of explainability methods in medical imaging. It connects explanation design with what matters to clinicians.</p><span>Shahab Ud Din et al. · Frontiers in Artificial Intelligence · Co-author</span></div><a class="work-arrow" aria-label="Read the explainable AI review" href="https://doi.org/10.3389/frai.2026.1819422">↗</a></article>
<article class="evidence-row"><p class="eyebrow">Intervention design · 2023</p><div><h3><a href="https://doi.org/10.1016/j.jbi.2022.104276">SATO: connecting intervention design with clinical goals</a></h3><p>An ontology-aligned workflow for patient-centred mobile behaviour-change interventions spanning multiple clinical goals. My contributions include conceptualization, methodology, analysis, and the original manuscript.</p><span>Lisowska, Wilk &amp; Peleg · Journal of Biomedical Informatics · First author</span></div><a class="work-arrow" aria-label="Read the SATO workflow paper" href="https://doi.org/10.1016/j.jbi.2022.104276">↗</a></article>
<article class="evidence-row"><p class="eyebrow">Sequential decisions · 2021</p><div><h3><a href="https://ceur-ws.org/Vol-3060/paper-2.pdf">Learning when to deliver a prompt</a></h3><p>A feasibility study of reinforcement learning for timely notifications and habit formation on synthetic data. The comparison with adaptive supervised learning exposes the importance of the decision formulation and evaluation baseline.</p><span>Lisowska, Wilk &amp; Peleg · SMARTERCARE · First author</span></div><a class="work-arrow" aria-label="Read the reinforcement learning feasibility study" href="https://ceur-ws.org/Vol-3060/paper-2.pdf">↗</a></article>
<article class="evidence-row"><p class="eyebrow">Uncertainty · AIME 2026</p><div><h3><a href="https://pure.amsterdamumc.nl/en/publications/detecting-silent-failures-in-rare-tumor-segmentation-the-impact-o/">Recognizing unreliable segmentation</a></h3><p>Examines how distributional shift affects uncertainty-aware quality assessment for rare tumor segmentation, testing the reliability of a model intended to assess another model’s output.</p><span>Paula Alfken et al. · AIME 2026 · Co-author</span></div><a class="work-arrow" aria-label="Read the rare tumor segmentation paper" href="https://pure.amsterdamumc.nl/en/publications/detecting-silent-failures-in-rare-tumor-segmentation-the-impact-o/">↗</a></article>
<a class="text-link all-publications" href="https://scholar.google.com/citations?user=-hXV9EsAAAAJ&amp;hl=en">Publication record on Google Scholar ↗</a></section>
<section class="section project-preview"><div class="section-title"><p class="eyebrow">Current programme</p><h2>Patient support.<br><em>Clinical decisions.</em></h2></div><div class="project-preview-list"><a href="projects.html#carepath"><span>01</span><div><h3>CAREPATH</h3><p>Reinforcement learning for personalized medication-adherence interventions.</p><small>My role: lead the reinforcement learning component</small></div><b aria-hidden="true">↗</b></a><a href="projects.html#clarity"><span>02</span><div><h3>CLARITY</h3><p>Testing whether tumour volume and boundary uncertainty carry information about treatment response.</p><small>My role: led the application and lead the joint project</small></div><b aria-hidden="true">↗</b></a><a href="projects.html#pulse-onc"><span>03</span><div><h3>PULSE-ONC</h3><p>Explainability and foundation models for oncology treatment monitoring.</p><small>VU–UT research collaboration</small></div><b aria-hidden="true">↗</b></a></div></section>
<section class="section agenda-section" id="agenda" aria-labelledby="agenda-title"><div class="section-title"><p class="eyebrow">Looking ahead · 2027–2031</p><h2 id="agenda-title">A research agenda for<br><em>AI-supported human decisions</em></h2><p class="intro">I aim to connect state estimation, action-conditioned transition modelling, and explainable sequential decisions with evaluation of survival and quality of life.</p></div><ol class="agenda-list"><li><span>01</span><div><h3>Explanations that support appropriate reliance</h3><p>Compare explanations with radiologists’ gaze and diagnostic reasoning, while separately testing faithfulness to model behaviour. Evaluate effects on diagnostic choices, reading time, confidence, and burden, especially when AI advice is wrong.</p><p class="agenda-question">Research question: can an explanation help a clinician detect a mistake, rather than make wrong advice more persuasive?</p></div></li><li><span>02</span><div><h3>Adaptive support under partial observability</h3><p>Develop uncertainty-aware patient-state estimates and models of transitions given actions. Study how reinforcement learning can use them to optimise expected longer-term outcomes, including the consequences of intervention timing.</p><p class="agenda-question">Research question: how should uncertainty in patient state influence the next action?</p></div></li><li><span>03</span><div><h3>Evaluation across models, people, and outcomes</h3><p>Connect technical evaluation and human decision studies with prospective evaluation of survival and patient-reported quality of life. Test whether intermediate improvements translate into the programme’s long-term objectives.</p><p class="agenda-question">Research question: when does a better model lead to a better decision?</p></div></li></ol></section>
<section class="section human-introduction"><p class="eyebrow">My role &amp; motivation</p><div><h2>A bridge between AI research<br><em>and cancer care</em></h2><p>At VU Computer Science and Cancer Center Amsterdam UMC, my role is to develop joint research questions, build projects, and supervise work across disciplines. Patient-facing reinforcement learning and clinician-facing imaging provide complementary settings for the same scientific questions.</p><p>My route here began with eye tracking, continued through industrial medical AI and personalised health support, and returned to imaging through clinical collaborations. It taught me to ask not only whether a model predicts well, but whether we are measuring and optimising the outcome that matters.</p><a class="text-link" href="research-journey.html">Read my research journey ↗</a></div></section>
<section class="collaboration-invitation" id="contact"><p class="eyebrow">Collaboration opportunities</p><h2>Build a programme around<br><em>a shared scientific question.</em></h2><div class="collaboration-options"><p><strong>Joint grants &amp; consortia</strong>Research programmes connecting explainability, uncertainty, and sequential decisions with evaluation in practice.</p><p><strong>Clinical partnerships</strong>Questions in treatment selection, response assessment, and personalized support, developed with clinical teams.</p><p><strong>Methodological collaborations</strong>Reinforcement learning, multimodal patient-state estimation, uncertainty quantification, and human–AI decision-making.</p></div><a class="button" href="mailto:a.j.lisowska@vu.nl?subject=Research%20collaboration">Discuss a research partnership ↗</a><a class="contact-email" href="mailto:a.j.lisowska@vu.nl">a.j.lisowska@vu.nl</a></section>''')

